content.text:
{
  "passageId": "missing-outlier-data",
  "items": [
    {
      "id": "R1",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "결측치 때문에 데이터의 특징을 나타내기 어렵다는 문제에 대해 다른 값으로 채우는 대체 방법을 제시한다."
    },
    {
      "id": "R2",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "이상치가 데이터의 특징을 왜곡하는 문제에 대해 중앙값을 대푯값으로 사용하는 대응 방법을 제시한다."
    },
    {
      "id": "R3",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "데이터 값이 빠져 있는 상태에 대응하여 다른 값으로 빈자리를 채우는 처리 방법을 제시한다."
    },
    {
      "id": "R4",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "중앙값의 일반적인 정의를 같은 값이 여러 개 있을 때의 산출 규칙으로 구체화한다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "중앙값의 일반적인 정의를 데이터 개수가 짝수일 때의 구체적인 산출 규칙으로 보충한다."
    },
    {
      "id": "R6",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "대체값으로 사용하는 세 값을 제시한 뒤 각각 어떤 데이터 유형에 사용하는지 자세히 설명한다."
    },
    {
      "id": "R7",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "이상치가 주로 측정 오류에서 생기지만 정상적인 데이터에도 존재할 수 있다고 일반적 설명의 한계를 밝힌다."
    },
    {
      "id": "R8",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "정상적인 데이터에도 특징을 왜곡하는 값이 있다는 설명을 유달리 높은 선수 연봉의 사례로 보여 준다."
    },
    {
      "id": "R9",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "유달리 높은 연봉과 같은 이상치가 포함된 데이터를 대표해야 하는 문제에 중앙값 사용이라는 대응 방법을 제시한다."
    },
    {
      "id": "R10",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "앞서 정의한 중앙값을 이상치가 포함된 데이터의 특징을 대표하는 용도로 가져다 쓴다."
    },
    {
      "id": "R11",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "앞서 설명한 이상치 개념을 평면상 점들의 위치라는 다른 데이터 영역에 적용하여 직선에서 멀리 떨어진 점을 판별한다."
    },
    {
      "id": "R12",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "직선 L을 기준으로 대부분의 점들은 가까이 모여 있고 이상치들은 멀리 떨어져 있다는 위치 차이를 대비한다."
    },
    {
      "id": "R13",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "직선 L과 이상치의 위치 관계를 설명하는 데서 이상치가 있는 데이터의 직선 L을 찾는 과제로 논의를 옮긴다."
    },
    {
      "id": "R14",
      "type": "PROCESS",
      "otherName": "",
      "reason": "두 점을 무작위로 고른 다음 그 점들을 초기 정상치 집합으로 가정하는 처리 순서이다."
    },
    {
      "id": "R15",
      "type": "PROCESS",
      "otherName": "",
      "reason": "초기 정상치 집합으로 가정한 두 점을 바탕으로 후보 직선을 만드는 다음 단계로 이어진다."
    },
    {
      "id": "R16",
      "type": "PROCESS",
      "otherName": "",
      "reason": "후보 직선을 그린 뒤 그 직선과 나머지 점들 사이의 거리를 계산하는 순서이다."
    },
    {
      "id": "R17",
      "type": "PROCESS",
      "otherName": "",
      "reason": "앞 단계에서 계산한 거리를 바탕으로 허용 범위 이내의 점들을 정상치 집합에 추가하는 다음 처리가 진행된다."
    },
    {
      "id": "R18",
      "type": "PROCESS",
      "otherName": "",
      "reason": "거리 기준으로 구성한 정상치 집합을 바탕으로 점 개수를 확인하여 후보 직선을 선별하는 다음 단계로 이어진다."
    },
    {
      "id": "R19",
      "type": "CONDITION",
      "otherName": "",
      "reason": "정상치 집합의 점 개수가 문턱값보다 많은지 적은지에 따라 후보 직선의 채택과 기각이 갈린다."
    },
    {
      "id": "R20",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "대부분의 점이 후보 직선에서 멀다는 사실과 앞서 제시한 선별 규칙으로부터 해당 직선이 제외된다는 결론을 도출한다."
    },
    {
      "id": "R21",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "정상치 수와 문턱값으로 후보를 선별하는 일반 규칙을 처음 선택한 점이 이상치인 경우에 적용한다."
    },
    {
      "id": "R22",
      "type": "PROCESS",
      "otherName": "",
      "reason": "후보 생성과 채택·기각으로 이루어진 처리 절차를 반복하여 최종 후보군을 만드는 과정이다."
    },
    {
      "id": "R23",
      "type": "PROCESS",
      "otherName": "",
      "reason": "반복 처리로 얻은 최종 후보군을 바탕으로 정상치 수가 최대인 직선을 고르는 다음 단계가 진행된다."
    },
    {
      "id": "R24",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "이상치로 만든 후보 직선이 제외된다는 작동 원리가 이상치가 있어도 직선 L을 찾을 가능성이 높다는 판단을 뒷받침한다."
    },
    {
      "id": "R25",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "후보 선별을 반복하고 정상치가 가장 많은 직선을 선택하는 절차가 직선 L을 찾을 가능성이 높다는 평가의 근거가 된다."
    }
  ]
}

